document.querySelectorAll('[data-download-cv]').forEach(function(button){button.addEventListener('click',function(){var raw=atob('');var bytes=new Uint8Array(raw.length);for(var i=0;i<raw.length;i++)bytes[i]=raw.charCodeAt(i);var url=URL.createObjectURL(new Blob([bytes],{type:'application/pdf'}));var link=document.createElement('a');link.href=url;link.download='Azam_Ansari_Technical_Support_Specialist_CV.pdf';document.body.appendChild(link);link.click();link.remove();setTimeout(function(){URL.revokeObjectURL(url);},60000);});});